import { prisma } from "@/lib/prisma"; // Kita panggil alat bantu tadi
import Image from "next/image";

// Ini namanya SERVER COMPONENT.
// Kodenya jalan di server, jadi database aman gak bisa diintip hacker.
export default async function PengurusPage() {
  // 1. Ambil data dari database (Simpel banget kan?)
  const semuaPengurus = await prisma.pengurus.findMany();

  return (
    <main className="min-h-screen bg-slate-950 pt-24 pb-12 px-4">
      <div className="max-w-7xl mx-auto">
        
        {/* Judul Halaman */}
        <div className="text-center mb-16">
          <h1 className="text-4xl md:text-5xl font-bold text-white mb-4">
            Struktur Organisasi
          </h1>
          <p className="text-slate-400 text-lg max-w-2xl mx-auto">
            Berkenalan dengan wajah-wajah di balik layar yang siap melayani dan menginspirasi.
          </p>
        </div>

        {/* Grid Card Pengurus */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {semuaPengurus.map((orang) => (
            <div 
              key={orang.id} 
              className="group relative bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden hover:border-blue-500/50 transition-all duration-300 hover:shadow-2xl hover:shadow-blue-900/20"
            >
              {/* Background Glow Effect saat di-hover */}
              <div className="absolute inset-0 bg-gradient-to-br from-blue-600/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

              <div className="p-6 flex flex-col items-center relative z-10">
                {/* Foto Profil Bulat */}
                <div className="w-32 h-32 mb-6 rounded-full border-4 border-slate-800 group-hover:border-blue-500 transition-colors shadow-xl overflow-hidden bg-slate-800">
                  <img
                    src={orang.foto || "https://via.placeholder.com/150"}
                    alt={orang.nama}
                    className="w-full h-full object-cover"
                  />
                </div>

                {/* Info Teks */}
                <h3 className="text-xl font-bold text-white mb-1 group-hover:text-blue-400 transition-colors">
                  {orang.nama}
                </h3>
                <span className="px-3 py-1 rounded-full bg-blue-900/30 text-blue-300 text-xs font-semibold tracking-wide uppercase border border-blue-500/20">
                  {orang.jabatan}
                </span>
              </div>
            </div>
          ))}
        </div>

      </div>
    </main>
  );
}